export function updateBoundElements(shape, scene) {
  for (const arrow of boundArrowsOf(shape, scene)) {
    const boundShape = shape
    const pointer = arrow.points[arrow.points.length - 1]
    // BUG SUSPECT: recomputes focus from the live pointer every move
    const focus = determineFocusPoint(arrow, boundShape, pointer)
    const gap = arrow.endBinding?.gap ?? 4
    arrow.endBinding = { ...arrow.endBinding, focus, gap }
    arrow.version += 1
    arrow.versionNonce = nextNonce()
  }
}
// determineFocusPoint returns a signed normalized offset; sign depends on which
// side of the shape center the pointer is on.
